/**
 * @component modal.footer
 * @memberOf modal
 * @selector .footer
 * @a11y Use real buttons in a logical focus order after the body, and include a visible dismiss action so keyboard users can close the dialog.
 * @summary The actions row (InstUI `Modal.Footer`).
 * @remarks The parent `modal`'s `-density-compact` and `-color-inverse` modifiers restyle this member — see `modal`'s own doc for those modifiers.
 * @structure
 * @component modal {
 *   .footer {
 *     @component button {}
 *   }
 * }
 * @example -automatica11y
 * ```html
 * <button class="pfx-button" command="--show" commandfor="account-dialog" data-a11y-trigger>Open account details</button>
 * <dialog class="pfx-modal -size-sm" id="account-dialog" aria-labelledby="account-dialog-title" data-a11y-root>
 *   <div class="header" id="account-dialog-title"><strong>Account details</strong></div>
 *   <div class="body">Review your account information.</div>
 *   <div class="footer"><button class="pfx-button" command="--close" commandfor="account-dialog">Close</button></div>
 * </dialog>
 * ```
 */
@scope (.pfx-modal) {
  :scope {
    > .footer {
      padding: var(--instui-component-modal-footer-padding);
      background: var(--instui-component-modal-footer-background-color);
      border-top: var(--instui-component-modal-footer-border-width) solid
        var(--instui-component-modal-footer-border-color);
      border-radius: 0 0 var(--instui-component-modal-footer-border-radius)
        var(--instui-component-modal-footer-border-radius);
    }

    &.-density-compact > .footer {
      padding: var(--instui-component-modal-footer-padding-compact);
    }

    &.-color-inverse > .footer {
      background: var(--instui-component-modal-footer-inverse-background-color);
      border-top-color: var(--instui-component-modal-footer-inverse-border-color);
    }
  }
}

