/**
 * @component billboard
 * @a11y Render the `.heading` as a real heading element. A `-clickable` billboard only gains hover styling, so give it `tabindex="0"`, an appropriate role, and a keyboard handler.
 * @summary A large empty-state or call-to-action block: a hero icon or image, a heading, and a message.
 * @remarks The `.hero`/`.heading`/`.message` parts are composed by the consumer's markup, not enforced structure; `-clickable` only adds hover styling, so a real click target still needs `tabindex` and a keyboard handler.
 * @modifier -clickable — Interactive (clickable) styling with hover feedback.
 * @modifier -icon-* — Render a leading icon glyph on `.hero` (e.g. `<span class="hero -icon-inbox"></span>`).
 * @modifier -size-sm — Small: tighter spacing with smaller heading, message, and hero icon.
 * @modifier -size-small — Long-form alias of {@link -size-sm}.
 * @modifier -size-md — Medium (default): standard spacing with medium heading, message, and hero icon.
 * @modifier -size-medium — Long-form alias of {@link -size-md}.
 * @modifier -size-lg — Large: roomier spacing with larger heading, message, and hero icon.
 * @modifier -size-large — Long-form alias of {@link -size-lg}.
 * @part .hero — The optional leading icon or image.
 * @part .heading — The billboard heading.
 * @part .message — The supporting message.
 * @compat Contains its element styles with the CSS `@scope` at-rule; needs a recent Chromium, Firefox, or Safari.
 * @example -canvas-rce -docs
 * ```html
 * <div class="pfx-billboard -size-md -clickable" tabindex="0">
 *   <span class="hero -icon-inbox"></span>
 *   <div class="heading">No items yet</div>
 *   <div class="message">Create your first item to get started.</div>
 * </div>
 * ```
 * @structure
 * .pfx-billboard {
 *   .hero:optional {}
 *   .heading {}
 *   .message {}
 * }
 * @todo `instructure-design-tokens` is missing several values defined in the `Billboard` component, so we hardcode them here for now. When the tokens are added, we should remove the hardcoded values and use the tokens instead.
 * @example -automatica11y
 * ```html
 * <div class="pfx-billboard -size-md -clickable" tabindex="0">
 *   <span class="hero -icon-inbox"></span>
 *   <div class="heading">No items yet</div>
 *   <div class="message">Create your first item to get started.</div>
 * </div>
 * ```
 */
.pfx-billboard {
  display: block;
  text-align: center;
  background: var(--instui-component-billboard-background-color);
  padding: var(--instui-component-billboard-padding-medium);
  margin: var(--instui-component-billboard-medium-margin);
  font-family: var(--instui-component-billboard-font-family);
  color: var(--instui-color-text-base);
}

.pfx-billboard.-size-sm {
  padding: var(--instui-component-billboard-padding-small);
}

.pfx-billboard.-size-md,
.pfx-billboard.-size-medium {
  padding: var(--instui-component-billboard-padding-medium);
}

.pfx-billboard.-size-lg {
  padding: var(--instui-component-billboard-padding-large);
  margin: var(--instui-component-billboard-large-margin);
}

.pfx-billboard.-size-large {
  padding: var(--instui-component-billboard-padding-large);
  margin: var(--instui-component-billboard-large-margin);
}

.pfx-billboard.-size-sm .message {
  font-size: var(--instui-font-size-text-sm);
}

.pfx-billboard.-size-md .message,
.pfx-billboard.-size-medium .message {
  font-size: var(--instui-font-size-text-base);
}

.pfx-billboard.-size-lg .message {
  font-size: 1.375rem;
}

.pfx-billboard.-size-large .message {
  font-size: 1.375rem;
}

.pfx-billboard.-clickable {
  cursor: pointer;
  border: var(--instui-component-billboard-button-border-width)
    var(--instui-component-billboard-button-border-style) transparent;
  border-radius: var(--instui-component-billboard-button-border-radius);
}

.pfx-billboard.-clickable:hover {
  border-style: dashed;
  border-color: var(--instui-color-text-base);
}

@media (--theme-canvas), (--theme-canvas-high-contrast) {
  .pfx-billboard.-clickable:hover {
    border-color: var(--instui-component-link-text-color);
  }
}

.pfx-billboard.-clickable:focus {
  border-style: solid;
  border-color: var(--instui-color-text-base);
  outline: var(--instui-focus-outline-width) var(--instui-focus-outline-style)
    var(--instui-focus-outline-color);
  outline-offset: var(--instui-focus-outline-offset);
}

@media (--theme-canvas), (--theme-canvas-high-contrast) {
  .pfx-billboard.-clickable:focus {
    border-style: dashed;
    border-color: var(--instui-component-link-text-color);
  }
}

.pfx-billboard.-clickable:focus-visible {
  outline: var(--instui-focus-outline-width) var(--instui-focus-outline-style)
    var(--instui-focus-outline-color);
  outline-offset: var(--instui-focus-outline-offset);
}

.pfx-billboard.-clickable:active {
  background: var(--instui-component-billboard-clickable-active-bg);
  border-style: solid;
  border-color: var(--instui-color-text-base);
}

@media (--theme-canvas), (--theme-canvas-high-contrast) {
  .pfx-billboard.-clickable:active {
    border-style: dashed;
    background: var(--instui-focus-outline-color);
    border-color: var(--instui-component-link-text-color);
  }
}

/* Fallback for environments where @scope is not applied: keep hero icon sizes in sync with size modifiers. */
.pfx-billboard > .hero {
  font-size: var(--instui-component-icon-illu-md);
}

.pfx-billboard > .hero:is([class^="-icon-"], [class*=" -icon-"]) {
  line-height: 1;
}

.pfx-billboard.-size-sm > .hero,
.pfx-billboard.-size-small > .hero {
  font-size: var(--instui-component-icon-illu-sm);
}

.pfx-billboard.-size-md > .hero,
.pfx-billboard.-size-medium > .hero {
  font-size: var(--instui-component-icon-illu-md);
}

.pfx-billboard.-size-lg > .hero,
.pfx-billboard.-size-large > .hero {
  font-size: var(--instui-component-icon-illu-lg);
}

@scope (.pfx-billboard) {
  :scope {
    /* The hero (an icon or image) leads the block. Size it via font-size on the glyph in the markup. */
    > .hero {
      display: inline-flex;
      justify-content: center;
      margin-block-end: var(--instui-spacing-space-sm);
      color: var(--instui-color-text-base);
      font-size: var(--instui-component-icon-illu-md);
    }

    /* The documented `-icon-*` modifier lives directly on .hero. */
    > .hero:is([class^="-icon-"], [class*=" -icon-"]) {
      line-height: 1;
    }

    &.-size-sm > .hero {
      font-size: var(--instui-component-icon-illu-sm);
    }

    &.-size-md > .hero,
    &.-size-medium > .hero {
      font-size: var(--instui-component-icon-illu-md);
    }

    &.-size-lg > .hero {
      font-size: var(--instui-component-icon-illu-lg);
    }

    &.-size-large > .hero {
      font-size: var(--instui-component-icon-illu-lg);
    }

    &.-size-sm > .hero:is([class^="-icon-"], [class*=" -icon-"]) {
      font-size: var(--instui-component-icon-illu-sm);
    }

    &.-size-small > .hero:is([class^="-icon-"], [class*=" -icon-"]) {
      font-size: var(--instui-component-icon-illu-sm);
    }

    &.-size-md > .hero:is([class^="-icon-"], [class*=" -icon-"]),
    &.-size-medium > .hero:is([class^="-icon-"], [class*=" -icon-"]) {
      font-size: var(--instui-component-icon-illu-md);
    }

    &.-size-lg > .hero:is([class^="-icon-"], [class*=" -icon-"]) {
      font-size: var(--instui-component-icon-illu-lg);
    }

    &.-size-large > .hero:is([class^="-icon-"], [class*=" -icon-"]) {
      font-size: var(--instui-component-icon-illu-lg);
    }

    /* The heading sits above the message — bolder and larger (Billboard renders a Heading here). */
    > .heading {
      margin: 0 0 var(--instui-spacing-space-xs);
      color: var(--instui-color-text-base);
      font-weight: bold;
      font-size: var(--instui-component-text-font-size-x-x-large);
    }

    > .message {
      color: var(--instui-color-text-base);
      font-size: var(--instui-font-size-text-base);
    }

    &.-clickable:hover > .hero {
      color: var(--instui-component-link-text-color);
    }

    &.-clickable:active > .hero {
      color: var(--instui-component-link-on-color-text-color);
    }
  }
}

