/**
 * @component menu.group
 * @memberOf menu
 * @selector .group
 * @a11y Wrap the grouped items in an element with `role="group"` and point `aria-labelledby` at the group heading so assistive technology announces the group name.
 * @summary A labelled group heading (InstUI `Menu.Group`/`Menu.ItemGroup`).
 * @structure
 * @component menu {
 *   .group {}
 * }
 * @example -automatica11y
 * ```html
 * <button class="pfx-button" type="button" popovertarget="actions-menu" aria-haspopup="menu" aria-controls="actions-menu" aria-expanded="false" data-a11y-trigger>Actions</button>
 * <div class="pfx-menu" id="actions-menu" popover="auto" role="menu" aria-label="Actions" data-menu-navigation data-a11y-root>
 *   <div role="group" aria-labelledby="editing-actions-label">
 *     <div class="group" id="editing-actions-label">Editing</div>
 *     <button class="item" type="button" role="menuitem">Edit</button>
 *     <button class="item" type="button" role="menuitem">Delete</button>
 *   </div>
 * </div>
 * ```
 */
@scope (.pfx-menu) {
  :scope {
    > .group,
    > [role="group"] > .group {
      padding: var(--instui-component-menu-group-padding-vertical)
        var(--instui-component-menu-group-padding-horizontal);
      background: var(--instui-component-menu-group-background);
      color: var(--instui-component-menu-group-color);
      font-family: var(--instui-component-menu-group-font-family);
      font-size: var(--instui-component-menu-group-font-size);
      font-weight: var(--instui-component-menu-group-font-weight);
    }
  }
}

