/**
 * @component simple-select
 * @a11y It's a native `<select>`, so role, keyboard support, and option announcement come from the browser; associate it with a visible `<label>` and convey errors in text, not color alone.
 * @summary A styled native `<select>` with a caret, matching the text-input states and sizes.
 * @remarks Wraps a plain native `<select>` with no custom dropdown/menu markup, so browser-native option rendering and keyboard behavior apply as-is; it shares its field chrome with `text-input`.
 * @selector .pfx-simple-select
 * @modifier -disabled — Disabled state.
 * @modifier -invalid — Invalid (error) state.
 * @modifier -readonly — Read-only state.
 * @modifier -success — Success (valid) state.
 * @modifier -size-sm — Small.
 * @modifier -size-md — (default) Medium.
 * @modifier -size-lg — Large.
 * @pseudo ::placeholder — The placeholder text, in a muted color that shifts on hover.
 * @cssstate disabled
 * @example -canvas-rce
 * <select class="pfx-simple-select">
 *   <option>Choose a fruit…</option>
 *   <option>Apple</option>
 *   <option>Orange</option>
 *   <option>Pear</option>
 * </select>
 * @example -automatica11y
 * ```html
 * <label>Fruit
 *   <select class="pfx-simple-select" data-a11y-trigger data-a11y-root>
 *     <option value="">Choose a fruit</option>
 *     <option value="apple">Apple</option>
 *     <option value="orange">Orange</option>
 *   </select>
 * </label>
 * ```
 * @example -docs
 * ```html
 * <label>Preferred contact method
 *   <select class="pfx-simple-select">
 *     <option value="email" selected>Email</option>
 *     <option value="phone">Phone</option>
 *     <option value="none">No contact</option>
 *   </select>
 * </label>
 * ```
 * @structure
 * .pfx-simple-select {
 *   option {}
 * }
 * @related text-input — Shares the same field chrome, states, and sizes.
 * @related menu — The dropdown surface a richer select reuses.
 */
@scope (.pfx-simple-select) {
  & {
    display: block;
    inline-size: 100%;
    box-sizing: border-box;
    font-family: var(--instui-component-text-input-font-family);
    font-weight: var(--instui-component-text-input-font-weight);
    color: var(--instui-component-text-input-text-color);
    background-color: var(--instui-component-text-input-background-color);
    border: var(--instui-component-text-input-border-width) solid
      var(--instui-component-text-input-border-color);
    border-radius: var(--instui-component-text-input-border-radius);
