/**
 * @component modal.header
 * @memberOf modal
 * @selector .header
 * @a11y Render the title as a real heading and point the dialog's `aria-labelledby` at it so the dialog is announced with its name.
 * @summary The title row (InstUI `Modal.Header`).
 * @remarks The parent `modal`'s `-density-compact` and `-color-inverse` modifiers restyle this member — see `modal`'s own doc for those modifiers.
 * @structure
 * @component modal {
 *   .header {
 *     strong {}
 *   }
 * }
 * @example -automatica11y
 * ```html
 * <button class="pfx-button" command="--show" commandfor="account-dialog" data-a11y-trigger>Open account details</button>
 * <dialog class="pfx-modal -size-sm" id="account-dialog" aria-labelledby="account-dialog-title" data-a11y-root>
 *   <div class="header" id="account-dialog-title"><strong>Account details</strong></div>
 *   <div class="body">Review your account information.</div>
 *   <div class="footer"><button class="pfx-button" command="--close" commandfor="account-dialog">Close</button></div>
 * </dialog>
 * ```
 */
@scope (.pfx-modal) {
  :scope {
    > .header {
      padding: var(--instui-component-modal-header-padding);
      background: var(--instui-component-modal-header-background-color);
      border-bottom: var(--instui-component-modal-header-border-width) solid
        var(--instui-component-modal-header-border-color);
    }

    &.-density-compact > .header {
      padding: var(--instui-component-modal-header-padding-compact);
    }

    &.-color-inverse > .header {
      background: var(--instui-component-modal-header-inverse-background-color);
      border-bottom-color: var(--instui-component-modal-header-inverse-border-color);
    }
  }
}

