/**
 * @component modal.body
 * @memberOf modal
 * @selector .body
 * @a11y Place the body inside the dialog that the header labels, and give a lone full-bleed `<img>` alt text.
 * @summary The content region (InstUI `Modal.Body`); a lone `<img>` goes full-bleed.
 * @remarks The parent `modal`'s `-overflow-fit`, `-density-compact`, and `-color-inverse` modifiers restyle this member — see `modal`'s own doc for those modifiers.
 * @structure
 * @component modal {
 *   .body {
 *     code {}
 *   }
 * }
 * @example -automatica11y
 * ```html
 * <button class="pfx-button" command="--show" commandfor="account-dialog" data-a11y-trigger>Open account details</button>
 * <dialog class="pfx-modal -size-sm" id="account-dialog" aria-labelledby="account-dialog-title" data-a11y-root>
 *   <div class="header" id="account-dialog-title"><strong>Account details</strong></div>
 *   <div class="body">Review your account information.</div>
 *   <div class="footer"><button class="pfx-button" command="--close" commandfor="account-dialog">Close</button></div>
 * </dialog>
 * ```
 */
@scope (.pfx-modal) {
  :scope {
    &.-overflow-fit > .body {
      overflow-y: auto;
    }

    > .body {
      padding: var(--instui-component-modal-body-padding);
    }

    /* A media modal: when the body holds an image it goes full-bleed (no padding) so the media meets the
     modal edges. Pair with -color-inverse for the on-dark chrome InstUI uses around media. */
    > .body:has(> img) {
      padding: 0;
    }

    > .body:has(> img) img {
      display: block;
      width: 100%;
    }

    &.-density-compact > .body {
      padding: var(--instui-component-modal-body-padding-compact);
    }

    &.-color-inverse > .body {
      background: var(--instui-component-modal-body-inverse-background-color);
    }
  }
}

