/**
 * @component input-group
 * @a11y Label the inner input with a real `<label>`. Mark purely visual icons in `.before` and `.after` with `aria-hidden="true"`, and convey `-invalid` and `-success` states in text, not color alone.
 * @summary A facade around a text input with leading and trailing icon slots.
 * @remarks Wraps the same field chrome as `text-input` with icon slots either side of it; `-should-not-wrap` is only needed when the group's contents would otherwise overflow onto a second line.
 * @selector .pfx-input-group
 * @modifier -disabled — Disabled state.
 * @modifier -invalid — Invalid (error) state.
 * @modifier -readonly — Read-only state.
 * @modifier -success — Success (valid) state.
 * @modifier -size-sm — Small.
 * @modifier -size-md — Medium.
 * @modifier -size-lg — Large.
 * @modifier -should-not-wrap — Keep the group on one line (no wrapping).
 * @part .before — The leading content slot.
 * @part .after — The trailing content slot.
 * @pseudo ::placeholder — The placeholder text of the inner input, in a muted color.
 * @cssstate disabled
 * @example -canvas-rce -docs
 * ```html
 * <span class="pfx-input-group">
 *   <span class="before">@</span>
 *   <input type="text" placeholder="username">
 * </span>
 * ```
 * @related text-input — Wraps a text input, adding leading and trailing icon slots.
 * @example -automatica11y
 * ```html
 * <label>Username <span class="pfx-input-group"><span class="before">@</span><input type="text" autocomplete="username"></span></label>
 * ```
 */
@scope (.pfx-input-group) {
  & {
    display: flex;
    align-items: center;
    inline-size: 100%;
    box-sizing: border-box;
    block-size: var(--instui-component-text-input-height-md);
    padding-inline: var(--instui-component-text-input-padding-horizontal-md);
    gap: var(--instui-component-text-input-gap-content);
    background-color: var(--instui-component-text-input-background-color);
    border: var(--instui-component-text-input-border-width) solid
      var(--instui-component-text-input-border-color);
    border-radius: var(--instui-component-text-input-border-radius);
    color: var(--instui-component-text-input-text-color);
    font-family: var(--instui-component-text-input-font-family);
    font-size: var(--instui-component-text-input-font-size-md);
  }

  &:hover {
    background-color: var(--instui-component-text-input-background-hover-color);
    border-color: var(--instui-component-text-input-border-hover-color);
  }

  /* The inner control is chromeless — the facade provides border/bg/ring. */
  & > input,
  & .pfx-text-input {
    flex: 1;
    min-inline-size: 0;
    border: 0;
    padding: 0;
    background: transparent;
    block-size: auto;
    font: inherit;
    color: inherit;
    outline: none;
