[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/pagination/members/page/page.css","old_str":" * @summary ","new_str":" * @a11y Mark the current page with `aria-current=\"page\"`, give each page an accessible name that includes the page number, and wrap the set in a `<nav>` with an `aria-label`.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/pill/pill.css","old_str":" * @summary ","new_str":" * @a11y The status colors are visual only, so state the status in the label text or a visually hidden label. The leading glyph is a masked `::before` and isn't announced.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/popover/popover.css","old_str":" * @summary ","new_str":" * @a11y Wire the trigger with `popovertarget` so the expanded state is exposed. A native popover closes on Escape and outside click but doesn't move focus, so move focus into interactive content when the popover opens.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/select/select.css","old_str":" * @summary ","new_str":" * @a11y It keeps native `<select>` semantics and keyboard behavior; associate it with a visible `<label>`, and check that the customized popup keeps a visible focus indicator and sufficient contrast.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/side-nav-bar/members/item/item.css","old_str":" * @summary ","new_str":" * @a11y Mark the active entry with `aria-current=\"page\"` as well as `-selected`, and keep an accessible name, such as `aria-label`, when the parent's `-minimized` modifier hides the `.label`.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/simple-select/simple-select.css","old_str":" * @summary ","new_str":" * @a11y It's a native `<select>`, so role, keyboard support, and option announcement come from the browser; associate it with a visible `<label>` and convey errors in text, not color alone.\n * @summary "}
