[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/list/list.css","old_str":" * @summary ","new_str":" * @a11y Use a real `<ul>` or `<ol>` with `<li>` children. Removing markers with `-unstyled` can make some screen readers drop the list semantics, so add `role=\"list\"` when the list structure matters.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/list/members/item/item.css","old_str":" * @summary ","new_str":" * @a11y Keep each item a direct `<li>` child of the list so it stays in the list's accessibility tree; delimiters and markers are visual only.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/menu/members/group/group.css","old_str":" * @summary ","new_str":" * @a11y Wrap the grouped items in an element with `role=\"group\"` and point `aria-labelledby` at the group heading so assistive technology announces the group name.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/menu/members/separator/separator.css","old_str":" * @summary ","new_str":" * @a11y Give the divider `role=\"separator\"` so assistive technology can announce the break between items; without it the rule is purely decorative.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/metric/metric.css","old_str":" * @summary ","new_str":" * @a11y The `.value` and `.label` are separate elements, so keep them adjacent in source order to read together, and don't convey meaning through size alone.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/modal/members/body/body.css","old_str":" * @summary ","new_str":" * @a11y Place the body inside the dialog that the header labels, and give a lone full-bleed `<img>` alt text.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/modal/members/footer/footer.css","old_str":" * @summary ","new_str":" * @a11y Use real buttons in a logical focus order after the body, and include a visible dismiss action so keyboard users can close the dialog.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/modal/members/header/header.css","old_str":" * @summary ","new_str":" * @a11y Render the title as a real heading and point the dialog's `aria-labelledby` at it so the dialog is announced with its name.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/pagination/members/page/page.css","old_str":" * @summary ","new_str":" * @a11y Mark the current page with `aria-current=\"page\"`, give each page an accessible name that includes the page number, and wrap the set in a `<nav>` with an `aria-label`.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/pill/pill.css","old_str":" * @summary ","new_str":" * @a11y The status colors are visual only, so state the status in the label text or a visually hidden label. The leading glyph is a masked `::before` and isn't announced.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/popover/popover.css","old_str":" * @summary ","new_str":" * @a11y Wire the trigger with `popovertarget` so the expanded state is exposed. A native popover closes on Escape and outside click but doesn't move focus, so move focus into interactive content when the popover opens.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/select/select.css","old_str":" * @summary ","new_str":" * @a11y It keeps native `<select>` semantics and keyboard behavior; associate it with a visible `<label>`, and check that the customized popup keeps a visible focus indicator and sufficient contrast.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/side-nav-bar/members/item/item.css","old_str":" * @summary ","new_str":" * @a11y Mark the active entry with `aria-current=\"page\"` as well as `-selected`, and keep an accessible name, such as `aria-label`, when the parent's `-minimized` modifier hides the `.label`.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/simple-select/simple-select.css","old_str":" * @summary ","new_str":" * @a11y It's a native `<select>`, so role, keyboard support, and option announcement come from the browser; associate it with a visible `<label>` and convey errors in text, not color alone.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/table/members/body/body.css","old_str":" * @summary ","new_str":" * @a11y Use a native `<tbody>` so row and cell relationships are exposed. The parent's `-layout-stacked` changes `display`, which can drop table semantics in some browsers, so add explicit table roles when you use it.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/table/members/cell/cell.css","old_str":" * @summary ","new_str":" * @a11y Use a native `<td>`. In `-layout-stacked` the column label is generated content that assistive technology may not announce reliably, so keep the column relationship available, for example with `headers`.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/table/members/col-header/col-header.css","old_str":" * @summary ","new_str":" * @a11y Use `<th scope=\"col\">` so each column header is associated with the cells beneath it.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/table/members/head/head.css","old_str":" * @summary ","new_str":" * @a11y Use a native `<thead>`. `-layout-stacked` hides it visually, so keep it in the DOM, not `display: none`, to preserve column names for assistive technology.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/table/members/row/row.css","old_str":" * @summary ","new_str":" * @a11y Use a native `<tr>`. The `-hover` styling is visual only, so give a clickable row a real control rather than relying on the highlight.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/table/members/row-header/row-header.css","old_str":" * @summary ","new_str":" * @a11y Use `<th scope=\"row\">` so the cell names its row for assistive technology.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/tabs/members/panel/panel.css","old_str":" * @summary ","new_str":" * @a11y Give each panel `role=\"tabpanel\"` and an `aria-labelledby` that references its tab, and keep inactive panels `hidden`.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/tabs/members/tab/tab.css","old_str":" * @summary ","new_str":" * @a11y Use `role=\"tab\"` inside a `role=\"tablist\"`, mirror `-selected` with `aria-selected`, point `aria-controls` at the panel, and mark a disabled tab with `aria-disabled` or the native `disabled`.\n * @summary "}
[tool edit] args={"path":"/Users/dwahl/Scripts/pantoken/formats/components/src/components/tag/tag.css","old_str":" * @summary ","new_str":" * @a11y Don't rely on color alone to distinguish tags. Give a removable tag's dismiss control an accessible name that includes the tag text, for example `aria-label=\"Remove Biology\"`.\n * @summary "}

