      position === -1
        ? `${md.trimEnd()}\n\n${section}`
        : `${md.slice(0, position)}${section}${md.slice(position)}`;
    writeFileSync(path, md);
  });
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
