        target: id,
        theme: item.theme,
        scheme: item.scheme,
        source: name.startsWith("npm-") ? "npm" : "page",
        run: basename(directory),
        date: string(results.runAt),
        tools,
        digest: createHash("sha256").update(raw).digest("hex"),
        warnings,
        notices: notices.filter(
