        writable: true,
        configurable: true,
      });
    }
  }
  for (const id of cases.keys())
    if (!seenTargets.has(id) && !seenTargets.has(`npm-${id}`))
      throw new Error(`Incomplete case inventory: ${id}`);
  if (!Object.keys(records).length) throw new Error("No supported accessibility evidence");
