             .map(([status, count]) => `${status} ${count}`)
             .join(", ")}`,
       )
       .join("; ");
     lines.push(
       `| ${cell(row.theme)} | ${cell(row.scheme)} | ${row.source === "page" ? text.page : text.npm} | ${row.configurations} | ${cell(tiers)} |`,
     );
   }
   lines.push(
     "",
     `| ${text.engine} | ${text.violations} | ${text.reviews} |`,
     "| --- | ---: | ---: |",
     `| axe-core | ${sum(rows, "axe", "violations")} | ${sum(rows, "axe", "reviews")} |`,
     `| IBM Equal Access | ${sum(rows, "ibm", "violations")} | ${sum(rows, "ibm", "reviews")} |`,
     "",
     text.reviewNote,
     "",
     `| ${text.checks} | pass | fail | not-applicable | undetermined |`,
     "| --- | ---: | ---: | ---: | ---: |",
   );
   for (const tier of ["conditions", "interactions", "computed"]) {
     const counts: Counts = {};
     for (const row of rows)
       for (const [result, count] of Object.entries(row.checks[tier] ?? {}))
         increment(counts, result, count);
     if (Object.keys(counts).length)
       lines.push(
         `| ${tier} | ${counts.pass ?? 0} | ${counts.fail ?? 0} | ${counts["not-applicable"] ?? 0} | ${counts.undetermined ?? 0} |`,
       );
   }
   lines.push(
     "",
     `${text.simulatedFlags}: ${rows.reduce((total, row) => total + row.flags, 0)}.`,
     "",
     text.limitations,
     "",
     "### " + text.details,
     "",
   );
   for (const row of rows) {
     lines.push(
       `- ${cell(row.target)} (${cell(row.date)}). ${cell(row.run)}.`,
       `  - ${text.tools}: ${Object.entries(row.tools)
         .map(([name, version]) => `${cell(name)} ${cell(version)}`)
         .join(", ")}.`,
     );
     for (const engine of ["axe", "ibm"] as const) {
       for (const [rule, count] of Object.entries(row[engine].violationRules))
         lines.push(`  - ${engine}: ${cell(rule)} (${text.violations}: ${count}).`);
       for (const [rule, count] of Object.entries(row[engine].reviewRules))
         lines.push(`  - ${engine}: ${cell(rule)} (${text.reviews}: ${count}).`);
     }
     for (const detail of [...row.findings, ...new Set(row.notices)])
       lines.push(`  - ${cell(detail)}`);
   }
   lines.push("", text.caveat, "");
   return lines.join("\n");
 }

 /**
  * Append the audit to the end of the page's `## Accessibility` section, creating that section before
  * consumed tokens (or related links/end) when the record has no `@accessibility` block.
  */
 export function annotateAccessibility(
   entries: readonly { name: string; kind: string }[],
   pages: readonly string[],
   snapshot: AccessibilitySnapshot,
 ): void {
   entries.forEach((entry, index) => {
     if (entry.kind !== "component" && !snapshot.records[entry.name]) return;
     const path = pages[index];
     if (!path) throw new Error(`Missing CSS API page: ${entry.name}`);
     let md = readFileSync(path, "utf8");
     md = md.replace(
       /<!-- accessibility-audit:start -->[\s\S]*?<!-- accessibility-audit:end -->\n*/u,
       "",
     );
     const section = `<!-- accessibility-audit:start -->\n${accessibilitySection(entry.name, snapshot)}\n<!-- accessibility-audit:end -->\n\n`;
     const heading = /^## Accessibility\s*$/mu.exec(md);
     const next = (from: number): number => {
       const match = /^## /mu.exec(md.slice(from));
       return match ? from + match.index : -1;
     };
     if (heading) {
       const end = next(heading.index + heading[0].length);
       const head = end === -1 ? md.trimEnd() : md.slice(0, end).trimEnd();
       md = `${head}\n\n${section}${end === -1 ? "" : md.slice(end)}`;
     } else {
       const position = md.search(/^## (?:Tokens consumed|See also)\s*$/mu);
       const created = `## Accessibility\n\n${section}`;
       md =
         position === -1
           ? `${md.trimEnd()}\n\n${created}`
           : `${md.slice(0, position)}${created}${md.slice(position)}`;
     }

