    source: "page",
    configurations: 1,
    flags: 1,
    axe: { violations: 1, reviews: 1, violationRules: { "example-violation": 1 } },
    ibm: { violations: 0, reviews: 1 },
    checks: { conditions: { pass: 1, fail: 1, undetermined: 1, "not-applicable": 1 } },
