  expect(snapshot.records.button).toHaveLength(1);
  const row = snapshot.records.button![0]!;
  expect(row).toMatchObject({
    source: "page",
    configurations: 1,
    flags: 1,
    axe: { violations: 1, reviews: 1, violationRules: { "example-violation": 1 } },
