      if (seenTargets.has(id)) throw new Error(`Duplicate audit target: ${id}`);
      seenTargets.add(id);
      const item = cases.get(id.replace(/^npm-/u, ""));
      if (!item) throw new Error(`Unknown audit target: ${id}`);
