            if (result === "fail" || result === "undetermined")
              row.findings.push(`${string(check.name)} (${result}): ${string(check.detail)}`);
          }
        }
      }
    }
  }
  if (!row.configurations) throw new Error(`No archetypes: ${row.target}`);
