    status: "ran",
    violations: [{ id: "example-violation" }],
    incomplete: [{ ruleId: "example-review" }],
  };
  const config = {
    libA11y: "n/a",
    tiers: {
      rules: { status: "ran", engines: { axe: engine, ibm: { ...engine, violations: [] } } },
      conditions: {
        status: "ran",
        checks: [
          {
            name: "reflow",
            criteria: ["1.4.10"],
