  const snapshot = loadAccessibilitySnapshot(snapshotJson);
  expect(Object.keys(snapshot.records)).toHaveLength(76);
  expect(snapshot.records.badge).toHaveLength(4);
  expect(snapshot.records.alert).toHaveLength(8);
